 await page.locator('[data-live]').click();await page.waitForFunction(()=>document.querySelector('[data-strength-auto]')?.textContent.includes('实时自动更新'));checks.push({returnLive:true});
 const firstMover=page.locator('.five-minute-side button').first(),code=await firstMover.getAttribute('data-strength-focus');await firstMover.click();assert.equal(await page.locator('.strength-product-tabs [data-compare="'+code+'"]').getAttribute('aria-pressed'),'true');checks.push({moverClickSelectsCurve:code});
 await page.locator('.observation-pool-row [data-strength-pool="all"]').click();await page.locator('[data-compare-clear]').click();
